{"command":"cat <<'EOF' > test_fmt.py
import subprocess
import sys

def sim(data, cols, fmt, color):
    lines = []
    for i in range(0, max(1, len(data) + 1), cols):
        chunk = data[i:i+cols]
        # if len == 0, chunk is empty, still print one line.
        # if i == len(data) and len(data) % cols == 0, chunk is empty, print empty line
        if i == len(data) and len(data) > 0 and len(data) % cols != 0:
            break

        line = f"0x{i:06x}: "
        for b in chunk:
            if color:
                line += f"\x1b[38;5;{b}m"
            if fmt == 'x':
                line += f"0x{b:02x}"
            elif fmt == 'X':
                line += f"0x{b:02X}"
            elif fmt == 'o':
                line += f"0o{b:04o}"
            elif fmt == 'b':
                line += f"0b{b:08b}"
            if color:
                line += f"\x1b[0m "
            else:
                line += " "

        missing = cols - len(chunk)
        line += " " * (5 * missing)

        for b in chunk:
            c = chr(b) if 0x20 <= b <= 0x7e else "."
            if color:
                line += f"\x1b[38;5;{b}m{c}\x1b[0m"
            else:
                line += c

        lines.append(line)

    lines.append(f"   bytes: {len(data)}")
    return "\n".join(lines) + "\n"

with open("test.txt", "rb") as f:
    data = f.read()

out_sim = sim(data, 10, 'x', False)
out_bin = subprocess.check_output(["./executable", "test.txt", "--color=0"]).decode("utf-8")

if out_sim == out_bin:
    print("Match!")
else:
    print("Mismatch!")
    print("sim:")
    print(repr(out_sim))
    print("bin:")
    print(repr(out_bin))
