use std::env;
use std::io::{self, Read, IsTerminal};
use std::fs::File;

fn print_help(bin_name: &str) {
    println!("Futuristic take on hexdump, made in Rust.


Usage: {bin_name} [OPTIONS] [INPUTFILE]

Arguments:
  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin

Options:
  -c, --cols <columns>        Set column length
  -l, --len <len>             Set <len> bytes to read
  -f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]
  -t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]
  -a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]
  -u, --func <func_length>    Set function wave length
  -p, --places <func_places>  Set function wave output decimal places
  -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]
  -h, --help                  Print help
  -V, --version               Print version");
    std::process::exit(0);
}

fn err_clap(bin_name: &str, msg: &str) -> ! {
    eprintln!("error: {}\n\nUsage: {} [OPTIONS] [INPUTFILE]\n\nFor more information, try '--help'.", msg, bin_name);
    std::process::exit(2);
}

fn err_clap_val(bin_name: &str, msg: &str, possible: &str) -> ! {
    eprintln!("error: {}\n  [possible values: {}]\n\nFor more information, try '--help'.", msg, possible);
    std::process::exit(2);
}

fn err_missing_val(bin_name: &str, flag: &str) -> ! {
    eprintln!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", flag);
    std::process::exit(2);
}

fn err_multiple(bin_name: &str, flag: &str) -> ! {
    eprintln!("error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] [INPUTFILE]\n\nFor more information, try '--help'.", flag, bin_name);
    std::process::exit(2);
}

fn err_unexpected(bin_name: &str, arg: &str) -> ! {
    if arg.starts_with("-") {
        eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} [OPTIONS] [INPUTFILE]\n\nFor more information, try '--help'.", arg, arg, arg, bin_name);
    } else {
        eprintln!("error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [INPUTFILE]\n\nFor more information, try '--help'.", arg, bin_name);
    }
    std::process::exit(2);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let bin_path = args.get(0).cloned().unwrap_or_else(|| "executable".to_string());
    let bin_name = std::path::Path::new(&bin_path).file_name().unwrap_or_default().to_string_lossy().to_string();

    let mut cols: Option<String> = None;
    let mut len_val: Option<String> = None;
    let mut format: Option<String> = None;
    let mut color: Option<String> = None;
    let mut array: Option<String> = None;
    let mut func: Option<String> = None;
    let mut places: Option<String> = None;
    let mut prefix: Option<String> = None;
    let mut input_file: Option<String> = None;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" || arg == "--help" {
            print_help(&bin_name);
        } else if arg == "-V" || arg == "--version" {
            println!("hx 0.7.0");
            std::process::exit(0);
        } else if arg == "-c" || arg == "--cols" {
            if cols.is_some() { err_multiple(&bin_name, "--cols <columns>"); }
            if i + 1 < args.len() { cols = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--cols <columns>"); }
        } else if arg.starts_with("--cols=") {
            if cols.is_some() { err_multiple(&bin_name, "--cols <columns>"); }
            cols = Some(arg[7..].to_string());
        } else if arg.starts_with("-c") {
            if cols.is_some() { err_multiple(&bin_name, "--cols <columns>"); }
            cols = Some(arg[2..].to_string());
