            if i + 1 < args.len() { array = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--array <array_format>"); }
        } else if arg.starts_with("--array=") {
            if array.is_some() { err_multiple(&bin_name, "--array <array_format>"); }
            array = Some(arg[8..].to_string());
        } else if arg.starts_with("-a") {
            if array.is_some() { err_multiple(&bin_name, "--array <array_format>"); }
            array = Some(arg[2..].to_string());
        } else if arg == "-u" || arg == "--func" {
            if func.is_some() { err_multiple(&bin_name, "--func <func_length>"); }
            if i + 1 < args.len() { func = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--func <func_length>"); }
        } else if arg.starts_with("--func=") {
