            if format.is_some() { err_multiple(&bin_name, "--format <format>"); }
            format = Some(arg[9..].to_string());
        } else if arg.starts_with("-f") {
            if format.is_some() { err_multiple(&bin_name, "--format <format>"); }
            format = Some(arg[2..].to_string());
        } else if arg == "-t" || arg == "--color" {
            if color.is_some() { err_multiple(&bin_name, "--color <color>"); }
            if i + 1 < args.len() { color = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--color <color>"); }
        } else if arg.starts_with("--color=") {
            if color.is_some() { err_multiple(&bin_name, "--color <color>"); }
            color = Some(arg[8..].to_string());
        } else if arg.starts_with("-t") {
            if color.is_some() { err_multiple(&bin_name, "--color <color>"); }
            color = Some(arg[2..].to_string());
        } else if arg == "-a" || arg == "--array" {
            if array.is_some() { err_multiple(&bin_name, "--array <array_format>"); }
            if i + 1 < args.len() { array = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--array <array_format>"); }
        } else if arg.starts_with("--array=") {
            if array.is_some() { err_multiple(&bin_name, "--array <array_format>"); }
            array = Some(arg[8..].to_string());
        } else if arg.starts_with("-a") {
            if array.is_some() { err_multiple(&bin_name, "--array <array_format>"); }
            array = Some(arg[2..].to_string());
        } else if arg == "-u" || arg == "--func" {
            if func.is_some() { err_multiple(&bin_name, "--func <func_length>"); }
            if i + 1 < args.len() { func = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--func <func_length>"); }
        } else if arg.starts_with("--func=") {
            if func.is_some() { err_multiple(&bin_name, "--func <func_length>"); }
            func = Some(arg[7..].to_string());
        } else if arg.starts_with("-u") {
            if func.is_some() { err_multiple(&bin_name, "--func <func_length>"); }
            func = Some(arg[2..].to_string());
        } else if arg == "-p" || arg == "--places" {
            if places.is_some() { err_multiple(&bin_name, "--places <func_places>"); }
            if i + 1 < args.len() { places = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--places <func_places>"); }
        } else if arg.starts_with("--places=") {
            if places.is_some() { err_multiple(&bin_name, "--places <func_places>"); }
            places = Some(arg[9..].to_string());
        } else if arg.starts_with("-p") {
            if places.is_some() { err_multiple(&bin_name, "--places <func_places>"); }
            places = Some(arg[2..].to_string());
        } else if arg == "-r" || arg == "--prefix" {
            if prefix.is_some() { err_multiple(&bin_name, "--prefix <prefix>"); }
            if i + 1 < args.len() { prefix = Some(args[i+1].clone()); i += 1; }
            else { err_missing_val(&bin_name, "--prefix <prefix>"); }
        } else if arg.starts_with("--prefix=") {
            if prefix.is_some() { err_multiple(&bin_name, "--prefix <prefix>"); }
            prefix = Some(arg[9..].to_string());
        } else if arg.starts_with("-r") {
            if prefix.is_some() { err_multiple(&bin_name, "--prefix <prefix>"); }
            prefix = Some(arg[2..].to_string());
        } else if !arg.starts_with("-") {
            if input_file.is_none() { input_file = Some(arg.clone()); }
            else { err_unexpected(&bin_name, arg); }
        } else {
            err_unexpected(&bin_name, arg);
        }
        i += 1;
    }

    let cols_parsed = cols.map(|s| match s.parse::<usize>() {
        Ok(v) => v,
        Err(e) => {
            eprintln!("-c, --cols <integer> expected. {:?}", e);
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }).unwrap_or(10);

    let len_parsed = len_val.map(|s| match s.parse::<usize>() {
        Ok(v) => v,
        Err(e) => {
            eprintln!("-l, --len <integer> expected. {:?}", e);
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    });

    let func_parsed = func.map(|s| match s.parse::<usize>() {
        Ok(v) => v,
        Err(e) => {
            eprintln!("-u, --func <integer> expected. {:?}", e);
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    });

    let mut places_parsed = 4;
    if func_parsed.is_some() {
        if let Some(s) = places {
            match s.parse::<usize>() {
                Ok(v) => places_parsed = v,
                Err(e) => {
                    eprintln!("-p, --places <integer> expected. {:?}", e);
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
        }
    }

    let format_val = format.unwrap_or_else(|| "x".to_string());
    if format_val != "x" && format_val != "X" && format_val != "o" && format_val != "b" {
        err_clap_val(&bin_name, &format!("invalid value '{}' for '--format <format>'", format_val), "o, x, X, b");
    }

    let color_val = color.map(|s| {
        if s != "0" && s != "1" {
            err_clap_val(&bin_name, &format!("invalid value '{}' for '--color <color>'", s), "0, 1");
        }
        s == "1"
    });

    let use_color = match color_val {
        Some(b) => b,
        None => {
            if env::var("NO_COLOR").is_ok() {
                false
            } else {
                io::stdout().is_terminal()
            }
        }
    };

    let prefix_val = prefix.map(|s| {
        if s != "0" && s != "1" {
            err_clap_val(&bin_name, &format!("invalid value '{}' for '--prefix <prefix>'", s), "0, 1");
        }
        s == "1"
    }).unwrap_or(true);

    let array_val = array.map(|s| {
        if s != "r" && s != "c" && s != "g" && s != "p" && s != "k" && s != "j" && s != "s" && s != "f" {
            err_clap_val(&bin_name, &format!("invalid value '{}' for '--array <array_format>'", s), "r, c, g, p, k, j, s, f");
        }
        s
    });

    let mut data = Vec::new();
    if let Some(path) = input_file {
        match File::open(&path) {
            Ok(mut f) => {
                if let Err(e) = f.read_to_end(&mut data) {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        if let Err(e) = io::stdin().read_to_end(&mut data) {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }

    if let Some(limit) = len_parsed {
        data.truncate(limit);
    }

    if let Some(u) = func_parsed {
        let places = places_parsed;
        for i in 0..u {
            let val = (std::f64::consts::PI * (i as f64) / (2.0 * (u as f64))).sin();
            print!("{:.*},", places, val);
        }
        println!();
        return;
    }

    let l = data.len();

    if let Some(lang) = array_val {
        let (out_start, out_end, sep, trail) = match lang.as_str() {
            "r" => (format!("let ARRAY: [u8; {}] = [\n", l), "];\n", ", ", false),
            "c" => (format!("unsigned char ARRAY[{}] = {{\n", l), "};\n", ", ", false),
            "g" => (format!("a := [{}]byte{{\n", l), "}\n", ", ", true),
            "p" => ("a = [\n".to_string(), "]\n", ", ", false),
            "k" => ("val a = byteArrayOf(\n".to_string(), ")\n", ", ", false),
            "j" => ("byte[] a = new byte[]{\n".to_string(), "};\n", ", ", false),
            "s" => ("let a: [UInt8] = [\n".to_string(), "]\n", ", ", false),
            "f" => ("let a = [|\n".to_string(), "|]\n", "; ", false),
            _ => unreachable!()
        };

        print!("{}", out_start);
        if l > 0 {
            for i in (0..l).step_by(cols_parsed) {
                print!("    ");
                let chunk_end = std::cmp::min(i + cols_parsed, l);
                for j in i..chunk_end {
                    let b = data[j];
                    if lang == "f" {
                        print!("0x{:02x}uy", b);
                    } else {
                        print!("0x{:02x}", b);
                    }
                    let is_last = j == l - 1;
                    if !is_last || trail {
                        print!("{}", sep);
                    }
                }
                println!();
            }
        }
        print!("{}", out_end);
        return;
    }

    let cols = cols_parsed;
    for i in (0..std::cmp::max(1, l + 1)).step_by(cols) {
        if i == l && l > 0 && l % cols != 0 {
            break;
        }
        let chunk_end = std::cmp::min(i + cols, l);
        let chunk = &data[i..chunk_end];

        print!("0x{:06x}: ", i);
        for &b in chunk {
            if use_color {
                print!("\x1b[38;5;{}m", b);
            }
            if prefix_val {
                match format_val.as_str() {
                    "x" => print!("0x{:02x}", b),
                    "X" => print!("0x{:02X}", b),
                    "o" => print!("0o{:04o}", b),
                    "b" => print!("0b{:08b}", b),
                    _ => unreachable!()
                }
            } else {
                match format_val.as_str() {
                    "x" => print!("{:02x}", b),
                    "X" => print!("{:02X}", b),
                    "o" => print!("{:04o}", b),
                    "b" => print!("{:08b}", b),
                    _ => unreachable!()
                }
            }
            if use_color {
                print!("\x1b[0m ");
            } else {
                print!(" ");
            }
        }

        let missing = cols - chunk.len();
        for _ in 0..missing {
            print!("     ");
        }

        for &b in chunk {
            let c = if b >= 0x20 && b <= 0x7e { b as char } else { '.' };
            if use_color {
                print!("\x1b[38;5;{}m{}\x1b[0m", b, c);
            } else {
                print!("{}", c);
            }
        }
        println!();
    }
    println!("   bytes: {}", l);
}
